mapper.select:
SELECT t.mkt03_history_id AS history_id , t.mkt03_person_id AS person_id , t.mkt03_reg_date AS reg_date , t.mkt03_target_company_id AS target_company_id , t.mkt03_target_company_nm AS target_company_name , t.mkt03_activity_date AS activity_date , t.mkt03_activity_title AS activity_title , t.mkt03_activity_content AS activity_content , t.mkt03_person_org_nm AS person_org_name , t.mkt03_file_count AS file_count , t.mkt03_fund_info AS fund_info , t.mkt03_share_info AS share_info FROM ( SELECT mkt03_history.* , mkt01_target_company_nm AS mkt03_target_company_nm , f_get_empTrans(mkt03_person_id, mkt03_activity_date, 'person_org_info') AS mkt03_person_org_nm , ( SELECT COUNT(*)||'건' FROM sys10_file WHERE sys10_parent_id = mkt03_history_id ) AS mkt03_file_count , fund_info AS mkt03_fund_info , () AS mkt03_share_info FROM mkt03_history INNER JOIN mkt01_target_company ON mkt01_target_company_id = mkt03_target_company_id LEFT OUTER JOIN () fnd ON history_id = mkt03_history_id WHERE mkt03_company_id = #{companyId} AND mkt03_activity_date BETWEEN #{startDate}::date AND #{closeDate}::date AND ( #{personId} IN ( SELECT mkt03_person_id UNION ALL SELECT mkt05_person_id FROM mkt05_share WHERE mkt05_parent_id = mkt03_history_id AND mkt05_share_cd = '1' ) OR #{orgId} IN ( SELECT mkt05_org_id FROM mkt05_share WHERE mkt05_parent_id = mkt03_history_id AND mkt05_share_cd = '2' ) )
AND mkt03_target_company_id = #{targetCompanyId}
AND mkt01_item_type_cd LIKE #{itemType} ) t WHERE UPPER(CONCAT(mkt03_target_company_nm, mkt03_activity_title, mkt03_person_org_nm)) LIKE UPPER(#{searchText}) ORDER BY mkt03_activity_date DESC, mkt03_target_company_nm COLLATE "ko_KR.utf8" ASC

SELECT mkt03_person_id
  FROM mkt03_history
 WHERE mkt03_history_id = #{historyId}
   AND mkt03_company_id = #{companyId}

