   SET mkt03_activity_date    = #{r.activityDate}
     , mkt03_activity_title   = #{r.activityTitle}
     , mkt03_activity_content = #{r.activityContent}
 WHERE mkt03_history_id = #{r.historyId}
   AND mkt03_company_id = #{companyId}

